import React, { useState, useEffect } from "react";

const ScheduleTable = ({ schedule, title, showSala = true, editable = false, onDataChange }) => {
  const [showPopup, setShowPopup] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({});
  const [scheduleData, setScheduleData] = useState([]);

  const fetchScheduleData = () => {
    fetch("http://localhost:34101/orar")
      .then((res) => res.json())
      .then((data) => {
        setScheduleData(data);
      })
      .catch((err) => console.error("Eroare la fetch:", err));
  };

  useEffect(() => {
    fetchScheduleData();
  }, []);

  const handleSaveEdit = () => {
    const isNew = selectedEntry && selectedEntry.id == null;

    const payload = { ...formData };
    if (isNew) delete payload.id;

    const url = isNew
      ? "http://localhost:34101/orar"
      : `http://localhost:34101/orar/${selectedEntry.id}`;
    const method = isNew ? "POST" : "PUT";

    fetch(url, {
      method,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then((res) => {
        if (!res.ok) throw new Error("Eroare la salvare");
        return res.json();
      })
      .then(() => {
        fetchScheduleData(); // Refă fetch-ul pentru a sincroniza datele
        closePopup();
      })
      .catch((err) => console.error("Eroare la salvare:", err));
  };

  const handleDeleteEntry = () => {
    fetch(`http://localhost:34101/orar/${selectedEntry.id}`, {
      method: "DELETE",
    })
      .then((res) => {
        if (res.ok) {
          fetchScheduleData(); // Refă fetch-ul pentru a sincroniza datele
          closePopup();
        }
      })
      .catch((err) => console.error("Eroare la ștergere:", err));
  };

  const handleAddNew = () => {
    const newEntry = {
      id: null,
      zi: "Luni",
      interval: "08:00 - 10:00",
      disciplina: "Nouă Disciplina",
      tip: "Curs",
      grupa: "A1",
      sala: "C101",
      profesor: "Profesor Nou",
      an: 1,
    };

    setSelectedEntry(newEntry);
    setFormData(newEntry);
    setShowPopup(true);
    setIsEditing(true);
  };

  return (
    <div className="schedule-table-container">
      <h2>{title}</h2>
      <table className="schedule-table">
        <thead>
          <tr>
            <th>Zi</th>
            <th>Interval</th>
            <th>Disciplina</th>
            <th>Tip</th>
            <th>Grupa</th>
            {showSala && <th>Sală</th>}
            <th>Profesor</th>
            <th>An</th>
            {editable && <th>Acțiuni</th>}
          </tr>
        </thead>
        <tbody>
          {scheduleData.length === 0 ? (
            <tr>
              <td colSpan={showSala ? (editable ? 9 : 8) : (editable ? 8 : 7)} style={{ textAlign: "center" }}>
                Nu există date disponibile pentru afișare.
                {editable && (
                  <div style={{ marginTop: "10px" }}>
                    <button className="add-button" onClick={handleAddNew}>➕ Adaugă o intrare nouă</button>
                  </div>
                )}
              </td>
            </tr>
          ) : (
            scheduleData.map((entry) => (
              <tr key={entry.id}>
                <td>{entry.zi}</td>
                <td>{entry.interval}</td>
                <td>{entry.disciplina}</td>
                <td>{entry.tip}</td>
                <td>{entry.grupa}</td>
                {showSala && <td>{entry.sala}</td>}
                <td>{entry.profesor}</td>
                <td>{entry.an}</td>
                {editable && (
                  <td>
                    <button className="edit-button" onClick={() => handleEditClick(entry)}>
                      ✏️ Editare
                    </button>
                  </td>
                )}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default ScheduleTable;
